native_supervisor.source:
param([ValidateSet('qa','infer')][string]$Mode,[string]$SourceCommit)
$ErrorActionPreference='Stop'
$taskRoot='E:/03-nn_Transfer_Func/kiki'
$taskBase=Join-Path $taskRoot 'private_data/closure_mechanism_20261019/P3/disagreement01'
$taskCap=if($Mode -eq 'qa'){300}else{3600}
$taskName=if($Mode -eq 'qa'){'qa01'}else{'inference01'}
$taskOutput=Join-Path $taskBase $taskName
if(Test-Path -LiteralPath $taskOutput){throw 'Unique registered output already exists'}
$taskArguments=if($Mode -eq 'qa'){@('experiments/closure_p3_disagreement_20261020.py','qa','--output',$taskOutput,'--max-seconds',[string]$taskCap)}else{@('experiments/closure_p3_disagreement_20261020.py','infer','--output',$taskOutput,'--manifest',(Join-Path $taskBase 'frozen_source_train_only.json'),'--max-seconds',[string]$taskCap)}
$taskStart=Get-Date
$taskTimer=[Diagnostics.Stopwatch]::StartNew()
$taskProcess=$null
$taskCleanup=$null
$taskFinished=$false
$taskError=$null
try {
 $taskProcess=Start-Process -FilePath (Join-Path $taskRoot '.venv-gpu/Scripts/python.exe') -ArgumentList $taskArguments -WorkingDirectory $taskRoot -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $taskBase "$taskName.stdout.log") -RedirectStandardError (Join-Path $taskBase "$taskName.stderr.log")
 @{source_commit=$SourceCommit;mode=$Mode;native_supervisor_pid=$PID;launcher_pid=$taskProcess.Id;start=$taskStart.ToString('o');cap_seconds=$taskCap;output=$taskOutput} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $taskBase "$taskName.native.running.json") -Encoding utf8
 $taskFinished=$taskProcess.WaitForExit(($taskCap-3)*1000)
 if(-not $taskFinished){$taskCleanup=(& taskkill /PID $taskProcess.Id /T /F 2>&1 | Out-String);[void]$taskProcess.WaitForExit(2000)}
} catch {$taskError=$_.Exception.Message} finally {
 if($null -ne $taskProcess -and -not $taskProcess.HasExited){$taskCleanup=(& taskkill /PID $taskProcess.Id /T /F 2>&1 | Out-String);[void]$taskProcess.WaitForExit(2000)}
 $taskTimer.Stop()
 $taskExit=$null
 if($null -ne $taskProcess){$taskProcess.Refresh();if($taskProcess.HasExited){$taskExit=$taskProcess.ExitCode}}
 $taskWorkerPath=Join-Path $taskOutput 'worker.json'
 $taskWorker=if(Test-Path -LiteralPath $taskWorkerPath){(Get-Content -Raw -LiteralPath $taskWorkerPath | ConvertFrom-Json).pid}else{$null}
 $taskComplete=($null -ne $taskProcess -and $taskProcess.HasExited)
 $taskStatus=if($taskFinished -and $taskExit -eq 0 -and $taskTimer.Elapsed.TotalSeconds -le $taskCap -and $null -eq $taskError){'COMPLETED'}else{'FAILED'}
 $taskReceipt=@{status=$taskStatus;source_commit=$SourceCommit;mode=$Mode;native_supervisor_pid=$PID;launcher_pid=$(if($null -ne $taskProcess){$taskProcess.Id}else{$null});actual_worker_pid=$taskWorker;start=$taskStart.ToString('o');end=(Get-Date).ToString('o');seconds=$taskTimer.Elapsed.TotalSeconds;cap_seconds=$taskCap;exit_code=$taskExit;native_receipt_complete=$taskComplete;includes_child_cost_once=$true;timeout=(-not $taskFinished);cleanup=$taskCleanup;error=$taskError;output=$taskOutput}
 [IO.File]::WriteAllText((Join-Path $taskBase "$taskName.native.receipt.json"),($taskReceipt | ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
 $taskReceipt | ConvertTo-Json -Compress -Depth 8
}
if($taskStatus -ne 'COMPLETED'){exit 1}
